/// Create routes for state transitions.
pub fn create_gamification_goal_transition_routes(service: Arc<GamificationGoalService>) -> Router {
    use axum::routing::post;

    Router::new()
        .route("/gamification_goals/:id/transitions/start", post(start_transition))
        .route("/gamification_goals/:id/transitions/evaluate_met", post(evaluate_met_transition))
        .route("/gamification_goals/:id/transitions/manual_reach", post(manual_reach_transition))
        .route("/gamification_goals/:id/transitions/window_close", post(window_close_transition))
        .route("/gamification_goals/:id/transitions/cancel", post(cancel_transition))
        .with_state(service)
}

